mapper.select:
SELECT `id`, `userId`, `recordDate`, `mealKey`, `clientRecordId`, `score`, `kcal`, `carbs`,
       `protein`, `fat`, `fiber`, `itemsJson`, `acceptedAt`, `dayGoalKcal`, `createdAt`, `updatedAt`
FROM `DietRecords`
WHERE `userId` = #{userId}
  AND `recordDate` = #{recordDate}
ORDER BY FIELD(`mealKey`, 'breakfast', 'lunch', 'snack', 'dinner')
